<?php
namespace App\Filament\Admin\Resources\PrivilegedAccess\Pages;use App\Application\Security\PrivilegedAccessService;use App\Filament\Admin\Concerns\ServiceValidation;use App\Filament\Admin\Resources\PrivilegedAccess\PrivilegedAccessGrantResource;use Filament\Actions\Action;use Filament\Forms\Components\Textarea;use Filament\Resources\Pages\ViewRecord;final class ViewPrivilegedAccessGrant extends ViewRecord{protected static string$resource=PrivilegedAccessGrantResource::class;protected function getHeaderActions():array{return[Action::make('approve')->visible(fn()=>$this->record->status==='REQUESTED')->action(function(){if(ServiceValidation::run(fn()=>app(PrivilegedAccessService::class)->approve($this->record,auth()->user()))===null)return;}),Action::make('revoke')->color('danger')->visible(fn()=>$this->record->status==='APPROVED')->schema([Textarea::make('reason')->required()])->action(function(array$d){if(ServiceValidation::run(fn()=>app(PrivilegedAccessService::class)->revoke($this->record,$d['reason'],auth()->user()))===null)return;})];}}
